 #[test]fn union_of_possible_write_guards_is_covered_only_when_reset_guard_implies_it(){let n=u64::MAX;let ops=vec![op(K::X,n,n,3,n,0),op(K::X,n,n,3,n,1),op(K::BitStore0,n,n,n,2,n),op(K::BitStore1,n,n,n,2,0),op(K::BitStore1,n,n,n,2,1),op(K::Hmr,n,n,3,3,2),op(K::CX,n,3,2,n,n)];let p=checked(&ops,&[0,1,2],&[0,1,2]);assert!(p.nodes.iter().any(|n|n.k==QZERO&&n.g==0));let p=checked(&ops,&[0,1,2,3],&[0,1,2]);assert!(p.nodes.iter().any(|n|n.k==QZERO&&n.g!=0));}
 #[test]fn exact_guard_implication_truth_tables_and_negative_cases(){let mut e=Expr::default();let a=e.atom();let b=e.atom();let and=e.and(a,b);let or=e.or(a,b);let xor=e.xor(a,b);assert!(e.implies(and,a));assert!(e.implies(a,or));assert!(!e.implies(or,a));assert!(e.implies(a^1,and^1));assert!(e.implies(xor,or));assert!(!e.implies(or,xor));let mut many=1;for _ in 0..11{let atom=e.atom();many=e.and(many,atom);}let unrelated=e.atom();assert!(!e.implies(many,unrelated));}

 #[test]fn complementary_nested_guards_fuse_only_to_captured_common_guard(){let n=u64::MAX;let ops=vec![op(K::PushCondition,n,n,n,n,0),op(K::CX,n,0,2,n,1),op(K::BitInvert,n,n,n,1,n),op(K::CX,n,0,2,n,1),op(K::PopCondition,n,n,n,n,n)];let p=checked(&ops,&[0,1,2],&[0,1,2]);let gates:Vec<_>=p.nodes.iter().filter(|n|n.k==QCX).collect();assert_eq!(gates.len(),1);assert_eq!(p.guards[gates[0].g as usize],vec![0]);}
 #[test]fn independent_guards_do_not_get_or_fused_or_cancelled(){let n=u64::MAX;let ops=vec![op(K::CX,n,0,2,n,0),op(K::CX,n,0,2,n,1)];let p=checked(&ops,&[0,1,2],&[0,1,2]);assert_eq!(p.nodes.iter().filter(|n|n.k==QCX).count(),2);}
 #[test]fn guarded_value_programs_with_mutating_controls_match_full_protected_simulator(){let n=u64::MAX;let mut seed=0xa8d7135f23649b01u64;for _ in 0..128{let mut ops=vec![];for _ in 0..80{seed=seed.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);let t=(seed>>8)%4;let a=(t+1+(seed>>16)%3)%4;let b=(0..4).find(|&q|q!=t&&q!=a).unwrap();let guard=if seed&4!=0{n}else{(seed>>24)%2};ops.push(match seed%5{0=>op(K::X,n,n,t,n,guard),1=>op(K::CX,n,a,t,n,guard),2=>op(K::CCX,b,a,t,n,guard),3=>op(K::Swap,n,a,t,n,guard),_=>op(K::BitInvert,n,n,n,(seed>>32)%2,guard)});}checked(&ops,&[0,1,2,3],&[0,1,2,3]);}}

 #[test]fn valid_curve_fixture_reference_checks_group_and_distinct_points(){let c=audit_curve();c.verify();let p=c.mul(c.gx,c.gy,"0x2".parse().unwrap());assert!(c.is_on_curve(p.0,p.1));assert_ne!(p.0,c.gx);assert_eq!(c.add(c.gx,c.gy,c.gx,c.gy),p);}

 #[test]fn semantic_guards_canonicalize_distributivity_and_remove_unused_atoms(){let mut e=Expr::default();let a=e.atom();let b=e.atom();let ab=e.and(a,b);let anb=e.and(a,b^1);let distributed=e.xor(ab,anb);assert_eq!(distributed,a);let or=e.or(a,b);let left=e.and(or,a);assert_eq!(left,a);assert_ne!(or,a);}
 #[test]fn semantic_guard_keys_match_all_original_six_atom_assignments(){fn value(e:&Expr,v:u32,assignment:usize,atoms:&[u32])->bool{if v<=1{return v==1;}let(k,a,b)=e.nodes[(v/2-1)as usize];let x=if k==0{let bit=atoms.iter().position(|&x|x==v&!1).expect("original atom");assignment>>bit&1!=0}else if k==1{value(e,a,assignment,atoms)&&value(e,b,assignment,atoms)}else{value(e,a,assignment,atoms)^value(e,b,assignment,atoms)};x^(v&1!=0)}let mut e=Expr::default();let atoms:Vec<_>=(0..6).map(|_|e.atom()).collect();let mut pool=atoms.clone();let mut seed=0xa8d7135f23649b01u64;for _ in 0..500{seed=seed.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);let a=pool[(seed as usize)%pool.len()];let b=pool[((seed>>17)as usize)%pool.len()];let g=pool[((seed>>33)as usize)%pool.len()];let kind=seed%4;let result=match kind{0=>e.and(a,b),1=>e.xor(a,b),2=>e.or(a,b),_=>e.ite(g,a,b)};for assignment in 0..64{let av=value(&e,a,assignment,&atoms);let bv=value(&e,b,assignment,&atoms);let gv=value(&e,g,assignment,&atoms);let expected=match kind{0=>av&bv,1=>av^bv,2=>av|bv,_=>if gv{av}else{bv}};assert_eq!(value(&e,result,assignment,&atoms),expected);}if pool.len()<64{pool.push(result);}else{pool[((seed>>8)as usize)%64]=result;}}}
 #[test]fn distributed_classical_guard_allows_only_proved_quantum_value_cancellation(){let n=u64::MAX;let ops=vec![op(K::BitStore0,n,n,n,2,n),op(K::BitStore1,n,n,n,2,0),op(K::BitStore0,n,n,n,3,n),op(K::BitStore1,n,n,n,3,1),op(K::BitStore0,n,n,n,4,n),op(K::PushCondition,n,n,n,n,2),op(K::BitStore1,n,n,n,4,3),op(K::PopCondition,n,n,n,n,n),op(K::BitInvert,n,n,n,3,n),op(K::BitStore0,n,n,n,5,n),op(K::PushCondition,n,n,n,n,2),op(K::BitStore1,n,n,n,5,3),op(K::PopCondition,n,n,n,n,n),op(K::BitStore0,n,n,n,6,n),op(K::BitInvert,n,n,n,6,4),op(K::BitInvert,n,n,n,6,5),op(K::X,n,n,2,n,6),op(K::X,n,n,2,n,0)];let p=checked_known_bits(&ops,&[0,1]);assert_eq!(p.nodes.iter().filter(|n|n.k==QX).count(),0);}

